package com.kisanflow.controller;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler {record ErrorResponse(OffsetDateTime timestamp,int status,String error,String message){} private ResponseEntity<ErrorResponse> response(HttpStatus s,Exception e){return ResponseEntity.status(s).body(new ErrorResponse(OffsetDateTime.now(),s.value(),s.getReasonPhrase(),e.getMessage()));}@ExceptionHandler(NoSuchElementException.class) ResponseEntity<ErrorResponse> notFound(NoSuchElementException e){return response(HttpStatus.NOT_FOUND,e);}@ExceptionHandler({IllegalStateException.class,IllegalArgumentException.class}) ResponseEntity<ErrorResponse> badRequest(Exception e){return response(HttpStatus.BAD_REQUEST,e);}@ExceptionHandler(org.springframework.security.access.AccessDeniedException.class) ResponseEntity<ErrorResponse> forbidden(Exception e){return response(HttpStatus.FORBIDDEN,e);}@ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> unexpected(Exception e){return response(HttpStatus.INTERNAL_SERVER_ERROR,e);}}
